import java.io.*;
class Escritor {
    private FileWriter fw;
    Escritor(String n) throws IOException { fw = new FileWriter(n); }
    void cerrar() throws IOException { fw.close(); }
    void escribir(String c) throws IOException { fw.write(c + "\r\n"); }
}
class Main {
    public static void main(String args[]) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        Escritor e = new Escritor("texto.txt");
        String s;
        while(!(s = br.readLine()).equals("alto")) e.escribir(s);
        e.cerrar();
    }
}

CREATE TABLE ALUMNO (
    A_ID_ALUMNO NUMBER NOT NULL,
    A_NOMBRE    VARCHAR2(200) NOT NULL,
    A_TELEFONO  VARCHAR2(15),
    A_CLASE     VARCHAR2(1) NOT NULL,
    CONSTRAINT ALUMNO_PK PRIMARY KEY (A_ID_ALUMNO)
);

CREATE TABLE CALIFICACION (
    C_ID_ASIGNATURA NUMBER NOT NULL,
    C_ID_ALUMNO     NUMBER NOT NULL,
    C_NOTA          NUMBER NOT NULL,
    CONSTRAINT CALIFICACION_PK PRIMARY KEY (C_ID_ASIGNATURA, C_ID_ALUMNO)
);

